create table if not exists spiritual.spiritual_journal ( id bigint generated always as identity primary key, entry_date date not null default current_date, title text, content text not null, entry_type text default 'reflection' check (entry_type in ('reflection', 'dream', 'gratitude', 'goal', 'lesson', 'prayer', 'custom')), mood text, tags text[], is_private boolean default true, linked_ayah_id integer, user_id uuid not null references identity.profiles (id) default auth.uid(), tenant_id uuid references core.tenants (id), created_at timestamptz default now(), updated_at timestamptz default now() );
